function usePath(): [string, (path: string) => void] {
  const [path, setPath] = useState(() => `${window.location.pathname}${window.location.search}`);
  useEffect(() => {
    const listener = () => setPath(`${window.location.pathname}${window.location.search}`);
    window.addEventListener('popstate', listener);
    return () => window.removeEventListener('popstate', listener);
  }, []);
  const navigate = (to: string) => {
    window.history.pushState({}, '', to);
    setPath(to);
  };
  return [path, navigate];
}

function Logo({ compact = false }: { compact?: boolean }) {
  return <div className="brand" aria-label="OrçaAgenda">
    <span className="brand-mark"><CalendarDays size={18} strokeWidth={2.5} /></span>
    {!compact && <span>Orça<span>Agenda</span></span>}
  </div>;
}

function AppButton({ children, variant = 'primary', className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'ghost' | 'danger' }) {
  return <button className={`button button-${variant} ${className}`} {...props}>{children}</button>;
}

function StatusPill({ state }: { state: string }) {
  const text = state.replaceAll('_', ' ');
  return <span className={`status status-${state}`}>{text}</span>;
}

function EmptyState({ icon: Icon, title, text, action }: { icon: typeof Search; title: string; text: string; action?: ReactNode }) {
  return <div className="empty-state"><span className="empty-icon"><Icon size={23} /></span><h3>{title}</h3><p>{text}</p>{action}</div>;
}

function Setup({ navigate }: { navigate: (path: string) => void }) {
  const [step, setStep] = useState(1);
  const steps = [
    ['Contas gratuitas', 'Crie as contas Cloudflare e Supabase. Nenhum cartão é necessário para começar nos planos gratuitos.'],
    ['Banco e autenticação', 'Execute a migração SQL e configure as URLs de redirecionamento do Supabase.'],
    ['Chaves publicáveis', 'Copie somente URL do projeto e a chave anon publicável para o arquivo .env.'],
    ['Primeiro acesso', 'Cadastre o e-mail do administrador diretamente pela tela de login.'],
  ];
  return <main className="setup-shell">
    <section className="setup-hero"><Logo /><div className="eyebrow">CONFIGURAÇÃO GUIADA</div><h1>Comece com controle,<br />sem expor segredos.</h1><p>O assistente identifica o que falta e aponta exatamente onde cada ajuste deve ser feito. Nada é enviado para o OrçaAgenda antes de você salvar.</p>
      <div className="setup-note"><ShieldCheck size={18} /><span>Credenciais privilegiadas ficam apenas no Supabase e na Cloudflare, nunca neste painel.</span></div>
    </section>
    <section className="setup-card">
      <div className="step-dots" aria-label={`Etapa ${step} de 4`}>{steps.map((_, index) => <span key={index} className={index + 1 <= step ? 'active' : ''} />)}</div>
      <p className="overline">ETAPA {step} DE {steps.length}</p><h2>{steps[step - 1][0]}</h2><p className="muted">{steps[step - 1][1]}</p>
      {step === 1 && <div className="setup-checklist"><a href="https://dash.cloudflare.com/sign-up" target="_blank" rel="noreferrer">Criar conta Cloudflare <ExternalLink size={14} /></a><a href="https://supabase.com/dashboard/sign-up" target="_blank" rel="noreferrer">Criar conta Supabase <ExternalLink size={14} /></a><span>Escolha os planos <strong>Free</strong>; não ative upgrade, cartão ou teste pago.</span></div>}
      {step === 2 && <pre className="code-block">supabase db push{`\n`}# ou execute supabase/migrations/0001_initial.sql no SQL Editor</pre>}
      {step === 3 && <pre className="code-block">VITE_SUPABASE_URL=https://...supabase.co{`\n`}VITE_SUPABASE_ANON_KEY=eyJ...{`\n`}VITE_APP_URL=http://localhost:5173</pre>}
      {step === 4 && <div className="setup-checklist"><span>Em Supabase → Authentication → URL Configuration, inclua <strong>http://localhost:5173</strong> e depois seu endereço <strong>pages.dev</strong>.</span><span>Volte a esta tela após salvar o arquivo <strong>.env</strong> e reinicie <strong>npm run dev</strong>.</span></div>}
      <div className="setup-actions"><AppButton variant="ghost" disabled={step === 1} onClick={() => setStep(step - 1)}><ChevronLeft size={17} /> Voltar</AppButton>{step < steps.length ? <AppButton onClick={() => setStep(step + 1)}>Continuar <ArrowRight size={17} /></AppButton> : <AppButton onClick={() => navigate('/login')}>Abrir login <ArrowRight size={17} /></AppButton>}</div>
      <button className="text-link" onClick={() => navigate('/?tour=1')}>Ver tour visual do painel sem conexão <ArrowRight size={14} /></button>
    </section>
  </main>;
}

function Login({ navigate }: { navigate: (path: string) => void }) {
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [loading, setLoading] = useState(false); const [message, setMessage] = useState('');
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setMessage(''); setLoading(true);
    try {
      const client = requireSupabase(); const { error } = await client.auth.signInWithPassword({ email, password });
      if (error) throw error; navigate('/');
    } catch (error) { setMessage(error instanceof Error ? error.message : 'Não foi possível entrar.'); } finally { setLoading(false); }
  };
  return <main className="auth-shell"><section className="auth-brand"><Logo /><div><span className="eyebrow">ORGANIZAÇÃO COMERCIAL</span><h1>Orçamentos e horários no ritmo de cada empresa.</h1><p>Uma plataforma para encontrar potenciais clientes, apresentar uma demonstração responsável e operar a agenda após a contratação.</p></div><div className="auth-trust"><ShieldCheck size={19} /> Acesso individual, dados isolados por empresa e operações registradas.</div></section>
    <section className="auth-card"><div className="card-heading"><span className="icon-disc"><LockKeyhole size={19} /></span><h2>Entrar no painel</h2><p>Use o e-mail cadastrado no Supabase Auth.</p></div><form onSubmit={submit}><label>E-mail<input required type="email" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="voce@exemplo.com" /></label><label>Senha<input required type="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Sua senha" /></label>{message && <p className="form-error" role="alert">{message}</p>}<AppButton type="submit" disabled={loading} className="wide">{loading ? <LoaderCircle className="spin" size={17} /> : 'Entrar no OrçaAgenda'}<ArrowRight size={17} /></AppButton></form><button className="text-link" onClick={() => navigate('/recuperar-acesso')}>Esqueci minha senha</button><p className="auth-footnote">Ainda não há administrador? Crie o primeiro usuário no Supabase Auth e atribua a função na migração, conforme o tutorial.</p></section>
  </main>;
}

function RecoverAccess({ navigate }: { navigate: (path: string) => void }) {
  const [email, setEmail] = useState(''); const [sent, setSent] = useState(false); const [error, setError] = useState('');
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setError('');
    try { const client = requireSupabase(); const { error: resetError } = await client.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/login` }); if (resetError) throw resetError; setSent(true); } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível iniciar a recuperação.'); }
  };
  return <main className="auth-shell"><section className="auth-brand"><Logo /><div><span className="eyebrow">RECUPERAÇÃO SEGURA</span><h1>Recupere o acesso sem compartilhar sua senha.</h1><p>O Supabase envia o fluxo de redefinição para o e-mail informado, sujeito à configuração de e-mail da sua conta.</p></div></section><section className="auth-card"><div className="card-heading"><span className="icon-disc"><LockKeyhole size={19} /></span><h2>Redefinir senha</h2><p>Informe seu e-mail cadastrado.</p></div>{sent ? <div className="success-panel"><CheckCircle2 size={25} /><strong>Solicitação enviada</strong><p>Se o endereço existir, siga o link recebido no e-mail.</p></div> : <form onSubmit={submit}><label>E-mail<input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="voce@exemplo.com" /></label>{error && <p className="form-error">{error}</p>}<AppButton type="submit" className="wide">Enviar instruções <ArrowRight size={17} /></AppButton></form>}<button className="text-link" onClick={() => navigate('/login')}><ChevronLeft size={14} /> Voltar ao login</button></section></main>;
}

function PublicBooking({ slug, navigate }: { slug: string; navigate: (path: string) => void }) {
  const [company, setCompany] = useState<Company | null>(null); const [services, setServices] = useState<Service[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const [step, setStep] = useState(1); const [service, setService] = useState<Service | null>(null); const [date, setDate] = useState(''); const [time, setTime] = useState(''); const [name, setName] = useState(''); const [phone, setPhone] = useState(''); const [email, setEmail] = useState(''); const [result, setResult] = useState<BookingResult | null>(null); const [saving, setSaving] = useState(false); const [availableTimes, setAvailableTimes] = useState<string[]>([]); const [slotsLoading, setSlotsLoading] = useState(false);
  useEffect(() => {
    let alive = true;
    async function load() { try { const client = requireSupabase(); const { data: found, error: companyError } = await client.from('public_companies').select('*').eq('slug', slug).maybeSingle(); if (companyError) throw companyError; if (!found) throw new Error('Esta página de agendamento não está disponível.'); const typedCompany = found as Company; const { data: serviceData, error: serviceError } = await client.from('services').select('*').eq('company_id', typedCompany.id).eq('is_active', true).order('name'); if (serviceError) throw serviceError; if (alive) { setCompany(typedCompany); setServices((serviceData ?? []) as Service[]); } } catch (err) { if (alive) setError(err instanceof Error ? err.message : 'Falha ao carregar o agendamento.'); } finally { if (alive) setLoading(false); } }
    void load(); return () => { alive = false; };
  }, [slug]);
  useEffect(() => { let alive = true; async function findSlots() { if (!company || !service || !date) { setAvailableTimes([]); return; } setSlotsLoading(true); setTime(''); try { const client = requireSupabase(); const { data, error: slotError } = await client.rpc('available_slots', { p_company_id: company.id, p_service_id: service.id, p_date: date }); if (slotError) throw slotError; if (alive) setAvailableTimes(((data ?? []) as Array<{ slot_start: string }>).map((item) => item.slot_start)); } catch (err) { if (alive) { setAvailableTimes([]); setError(err instanceof Error ? err.message : 'Não foi possível consultar horários.'); } } finally { if (alive) setSlotsLoading(false); } } void findSlots(); return () => { alive = false; }; }, [company, service, date]);
  const today = new Date().toISOString().slice(0, 10);
  const book = async () => { if (!company || !service || !date || !time || !name) return; setSaving(true); setError(''); try { const startsAt = time; const client = requireSupabase(); const { data, error: rpcError } = await client.rpc('create_booking', { p_company_id: company.id, p_service_id: service.id, p_starts_at: startsAt, p_consumer_name: name, p_consumer_phone: normalizePhone(phone), p_consumer_email: email || null, p_idempotency_key: crypto.randomUUID() }); if (rpcError) throw rpcError; setResult((data as BookingResult[])[0]); setStep(6); } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível concluir. Verifique o horário e tente novamente.'); } finally { setSaving(false); } };
  if (loading) return <div className="public-loading"><LoaderCircle className="spin" /> Carregando agenda...</div>;
  if (error && !company) return <div className="public-loading"><div><Logo /><h1>Agenda indisponível</h1><p>{error}</p><AppButton onClick={() => navigate('/')}>Ir para OrçaAgenda</AppButton></div></div>;
  if (!company) return null;
  const steps = ['Serviço', 'Data', 'Horário', 'Seus dados', 'Revisão'];
  return <main className={`booking-shell theme-${company.theme_key}`}><header className="booking-header"><Logo /><div className="booking-business"><strong>{company.name}</strong><span>{company.city && company.state ? `${company.city} · ${company.state}` : 'Agendamento online'}</span></div></header><div className="booking-wrap"><section className="booking-main"><div className="booking-progress">{steps.map((label, index) => <div key={label} className={step >= index + 1 ? 'done' : ''}><span>{step > index + 1 ? <Check size={13} /> : index + 1}</span><small>{label}</small></div>)}</div>
    {step === 1 && <section className="booking-stage"><p className="overline">ETAPA 1</p><h1>Qual serviço você precisa?</h1><p className="muted">Escolha uma opção para ver os próximos horários.</p><div className="service-grid">{services.map((item) => <button className={`service-choice ${service?.id === item.id ? 'selected' : ''}`} onClick={() => setService(item)} key={item.id}><span><strong>{item.name}</strong><small>{item.description || 'Sem descrição adicional'}</small></span><b>{formatCurrency(item.price_cents)}</b><em>{item.duration_minutes} min</em></button>)}</div>{!services.length && <EmptyState icon={FileText} title="Serviços ainda não publicados" text="A empresa precisa configurar os serviços antes de receber reservas." />}</section>}
    {step === 2 && <section className="booking-stage"><p className="overline">ETAPA 2</p><h1>Escolha uma data</h1><p className="muted">Datas disponíveis respeitam as regras definidas pela empresa.</p><label className="date-picker">Data do atendimento<input type="date" min={today} value={date} onChange={(e) => setDate(e.target.value)} /></label></section>}
    {step === 3 && <section className="booking-stage"><p className="overline">ETAPA 3</p><h1>Selecione um horário</h1><p className="muted">O horário é confirmado somente depois da operação no servidor.</p><div className="time-grid">{slotsLoading ? <LoaderCircle className="spin" /> : availableTimes.map((option) => <button key={option} className={time === option ? 'selected' : ''} onClick={() => setTime(option)}>{new Intl.DateTimeFormat('pt-BR', { hour: '2-digit', minute: '2-digit' }).format(new Date(option))}</button>)}</div>{!slotsLoading && !availableTimes.length && <p className="muted">Nenhum horário disponível nesta data.</p>}</section>}
    {step === 4 && <section className="booking-stage"><p className="overline">ETAPA 4</p><h1>Seus dados de contato</h1><p className="muted">Use os dados necessários para a empresa atender sua solicitação.</p><div className="form-grid"><label>Nome completo<input value={name} onChange={(e) => setName(e.target.value)} autoComplete="name" /></label><label>Telefone<input value={phone} onChange={(e) => setPhone(e.target.value)} autoComplete="tel" /></label><label className="span-2">E-mail <small>(opcional)</small><input type="email" value={email} onChange={(e) => setEmail(e.target.value)} autoComplete="email" /></label></div></section>}
    {step === 5 && <section className="booking-stage"><p className="overline">ETAPA 5</p><h1>Confira seu pedido</h1><div className="review-card"><span>Serviço<strong>{service?.name}</strong></span><span>Quando<strong>{date ? new Intl.DateTimeFormat('pt-BR', { dateStyle: 'full' }).format(new Date(`${date}T12:00:00`)) : '—'} às {time ? new Intl.DateTimeFormat('pt-BR', { hour: '2-digit', minute: '2-digit' }).format(new Date(time)) : '—'}</strong></span><span>Valor<strong>{formatCurrency(service?.price_cents)}</strong></span><span>Contato<strong>{name || '—'}{phone ? ` · ${phone}` : ''}</strong></span></div>{error && <p className="form-error">{error}</p>}</section>}
    {step === 6 && <section className="booking-stage booking-confirmed"><span className="success-orb"><CheckCircle2 size={34} /></span><p className="overline">PEDIDO REGISTRADO</p><h1>{result?.state === 'confirmed' ? 'Seu horário foi confirmado.' : 'Pedido aguardando aprovação.'}</h1><p>Guarde este comprovante. A empresa poderá entrar em contato pelo dado informado.</p><div className="receipt"><span>Protocolo</span><strong>{result?.public_token}</strong><span>Serviço</span><strong>{service?.name}</strong><span>Horário</span><strong>{date} · {time ? new Intl.DateTimeFormat('pt-BR', { hour: '2-digit', minute: '2-digit' }).format(new Date(time)) : '—'}</strong><span>Valor</span><strong>{formatCurrency(result?.price_cents)}</strong></div></section>}
    {step < 6 && <div className="booking-actions"><AppButton variant="ghost" disabled={step === 1} onClick={() => setStep(step - 1)}><ChevronLeft size={17} /> Voltar</AppButton>{step < 5 ? <AppButton disabled={(step === 1 && !service) || (step === 2 && !date) || (step === 3 && !time) || (step === 4 && !name)} onClick={() => setStep(step + 1)}>Continuar <ArrowRight size={17} /></AppButton> : <AppButton disabled={saving} onClick={() => void book()}>{saving ? <LoaderCircle className="spin" size={17} /> : <Check size={17} />}Confirmar pedido</AppButton>}</div>}
  </section><aside className="booking-summary"><p className="overline">SEU RESUMO</p><div><span>Empresa</span><strong>{company.name}</strong></div><div><span>Serviço</span><strong>{service?.name || 'Escolha um serviço'}</strong></div><div><span>Duração</span><strong>{service ? `${service.duration_minutes} minutos` : '—'}</strong></div><div><span>Valor</span><strong>{formatCurrency(service?.price_cents)}</strong></div>{service?.price_type === 'manual' && <p className="summary-note">Este serviço será avaliado pela empresa antes de definir o valor final.</p>}</aside></div></main>;
}

function DemoPage({ token, navigate }: { token: string; navigate: (path: string) => void }) {
  const [company, setCompany] = useState<Company | null>(null); const [error, setError] = useState('');
  useEffect(() => { let alive = true; async function load() { try { const client = requireSupabase(); const { data, error: loadError } = await client.from('public_demos').select('*').eq('public_token', token).maybeSingle(); if (loadError) throw loadError; if (!data) throw new Error('Demonstração indisponível ou expirada.'); if (alive) setCompany(data as Company); } catch (err) { if (alive) setError(err instanceof Error ? err.message : 'Demonstração indisponível.'); } } void load(); return () => { alive = false; }; }, [token]);
  if (error) return <div className="public-loading"><div><Logo /><h1>Demonstração indisponível</h1><p>{error}</p></div></div>;
  if (!company) return <div className="public-loading"><LoaderCircle className="spin" /> Preparando demonstração...</div>;
  return <main className={`demo-page theme-${company.theme_key}`}><header className="demo-banner"><Logo /><span><ShieldCheck size={15} /> Proposta independente preparada por Nicolas — demonstração sem reservas ativas</span></header><section className="demo-hero"><p className="overline">EXEMPLO ILUSTRATIVO</p><h1>Uma experiência de orçamento e agendamento para <em>{company.name}</em>.</h1><p>{company.description || 'Uma proposta editável. Serviços, preços, contatos e horários devem ser confirmados com a empresa antes da ativação.'}</p><div><AppButton disabled>Reservas indisponíveis nesta demonstração</AppButton><AppButton variant="secondary" onClick={() => navigate('/')}>Conhecer OrçaAgenda</AppButton></div></section><section className="demo-tiles"><article><CalendarDays size={20} /><h3>Agenda organizada</h3><p>Etapas claras e disponibilidade baseada em regras reais após ativação.</p></article><article><FileText size={20} /><h3>Orçamentos responsáveis</h3><p>Serviços sem preço são encaminhados para avaliação, sem valores inventados.</p></article><article><MessageCircle size={20} /><h3>Contato no seu controle</h3><p>Mensagens podem ser preparadas, revisadas e enviadas manualmente.</p></article></section><footer className="demo-footer">Esta prévia não é site oficial de {company.name}, não coleta dados de consumidores e pode expirar.</footer></main>;
}

function Dashboard({ preview, navigate }: { preview: boolean; navigate: (path: string) => void }) {
  const [view, setView] = useState<View>('overview'); const [menuOpen, setMenuOpen] = useState(false); const [leads, setLeads] = useState<Lead[]>([]); const [companies, setCompanies] = useState<Company[]>([]); const [loading, setLoading] = useState(!preview); const [toast, setToast] = useState('');
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 3000); };
  const load = async () => { if (preview) return; setLoading(true); try { const client = requireSupabase(); const [{ data: leadData, error: leadError }, { data: companyData, error: companyError }] = await Promise.all([client.from('leads').select('*').order('created_at', { ascending: false }), client.from('companies').select('*').order('created_at', { ascending: false })]); if (leadError) throw leadError; if (companyError) throw companyError; setLeads((leadData ?? []) as Lead[]); setCompanies((companyData ?? []) as Company[]); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível carregar dados.'); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, [preview]);
  const activeNav = nav.find((item) => item.id === view)!;
  const switchView = (target: View) => { setView(target); setMenuOpen(false); };
  const logout = async () => { if (preview) { navigate('/setup'); return; } await supabase?.auth.signOut(); navigate('/login'); };
  return <div className="app-shell"><aside className={`sidebar ${menuOpen ? 'open' : ''}`}><div><Logo /><button className="mobile-close" onClick={() => setMenuOpen(false)} aria-label="Fechar menu"><X size={20} /></button></div><nav>{nav.map(({ id, label, icon: Icon }) => <button key={id} className={view === id ? 'active' : ''} onClick={() => switchView(id)}><Icon size={18} />{label}</button>)}</nav><div className="sidebar-bottom"><div className="owner-avatar">N</div><div><strong>Nicolas</strong><small>{preview ? 'Tour de visualização' : 'Administrador'}</small></div><button className="icon-button" onClick={() => void logout()} aria-label="Sair"><LogOut size={17} /></button></div></aside><div className="mobile-overlay" onClick={() => setMenuOpen(false)} />
    <main className="dashboard"><header className="dashboard-header"><div><button className="mobile-menu icon-button" onClick={() => setMenuOpen(true)} aria-label="Abrir menu"><Menu size={21} /></button><p className="overline">PAINEL NICOLAS</p><h1>{activeNav.label}</h1></div><div className="header-actions">{preview && <span className="preview-badge">Modo demonstração local</span>}<button className="icon-button" aria-label="Notificações"><Bell size={19} /><i /></button><AppButton onClick={() => switchView('leads')}><Plus size={17} /> Novo potencial</AppButton></div></header>{toast && <div className="toast"><CheckCircle2 size={17} />{toast}</div>}{loading ? <div className="panel-loading"><LoaderCircle className="spin" /> Carregando registros reais...</div> : <DashboardContent view={view} leads={leads} companies={companies} reload={load} preview={preview} notify={notify} navigate={navigate} />}</main></div>;
}

function DashboardContent({ view, leads, companies, reload, preview, notify, navigate }: { view: View; leads: Lead[]; companies: Company[]; reload: () => Promise<void>; preview: boolean; notify: (message: string) => void; navigate: (path: string) => void }) {
  if (view === 'overview') return <Overview leads={leads} companies={companies} onNavigate={navigate} />;
  if (view === 'leads') return <LeadBoard leads={leads} reload={reload} preview={preview} notify={notify} />;
  if (view === 'demos') return <DemoList companies={companies} preview={preview} notify={notify} />;
  if (view === 'deals') return <DealsBoard leads={leads} reload={reload} preview={preview} notify={notify} />;
  if (view === 'companies') return <CompanyList companies={companies} preview={preview} notify={notify} />;
  if (view === 'agenda') return <AgendaView companies={companies} preview={preview} />;
  if (view === 'services') return <ServiceManager companies={companies} preview={preview} notify={notify} />;
  return <SettingsView />;
}

function Overview({ leads, companies, onNavigate }: { leads: Lead[]; companies: Company[]; onNavigate: (path: string) => void }) {
  const active = companies.filter((company) => company.lifecycle === 'active').length; const demos = companies.filter((company) => company.lifecycle === 'demo').length; const noContact = leads.filter((lead) => lead.deal_stage === 'do_not_contact').length;
  return <div className="page-stack"><section className="metrics-grid"><Metric label="Potenciais em análise" value={leads.filter((lead) => lead.deal_stage !== 'do_not_contact').length} detail="Registros reais no funil" icon={Search} /><Metric label="Demonstrações ativas" value={demos} detail="Pré-visualizações não indexáveis" icon={WandSparkles} /><Metric label="Empresas ativas" value={active} detail="Com reservas habilitadas" icon={Store} /><Metric label="Não contatar" value={noContact} detail="Excluídos das filas" icon={ShieldCheck} /></section><section className="split-grid"><article className="surface action-card"><div><span className="icon-disc"><Sparkles size={18} /></span><p className="overline">FLUXO RECOMENDADO</p><h2>Transforme um potencial em demonstração, sem sair do painel.</h2><p>Cadastre uma fonte pública, revise o potencial e use <strong>Aceitar cliente e criar projeto</strong>. A demonstração continua editável e não habilita reservas.</p><AppButton onClick={() => onNavigate('/?tour=1')}>Rever tour de configuração <ArrowRight size={17} /></AppButton></div><div className="flow-steps"><span>1</span><i /><span>2</span><i /><span>3</span><small>Prospectar · Revisar · Apresentar</small></div></article><article className="surface"><div className="section-title"><div><p className="overline">PRÓXIMAS AÇÕES</p><h2>Sem suposições</h2></div><Gauge size={20} /></div>{leads.filter((lead) => lead.next_action_at && lead.deal_stage !== 'do_not_contact').slice(0, 3).map((lead) => <div className="mini-row" key={lead.id}><span className="initials">{lead.name.slice(0, 1)}</span><div><strong>{lead.name}</strong><small>{lead.next_action_at ? `Próxima ação: ${new Intl.DateTimeFormat('pt-BR').format(new Date(lead.next_action_at))}` : ''}</small></div><StatusPill state={lead.deal_stage} /></div>)}{!leads.some((lead) => lead.next_action_at && lead.deal_stage !== 'do_not_contact') && <EmptyState icon={ClipboardCheck} title="Nenhuma ação agendada" text="Defina a próxima ação ao registrar uma negociação." />}</article></section><section className="surface"><div className="section-title"><div><p className="overline">CONTROLE DE DADOS</p><h2>Operação preparada para começar</h2></div></div><div className="checklist-row"><div><CheckCircle2 size={18} /><span>Isolamento por empresa via RLS</span></div><div><CheckCircle2 size={18} /><span>Preço calculado no servidor</span></div><div><CheckCircle2 size={18} /><span>Importação CSV com proteção de fórmula</span></div><div><CheckCircle2 size={18} /><span>Mensagens somente para envio manual</span></div></div></section></div>;
}

function Metric({ label, value, detail, icon: Icon }: { label: string; value: number; detail: string; icon: typeof Gauge }) { return <article className="metric-card"><span className="metric-icon"><Icon size={19} /></span><p>{label}</p><strong>{value}</strong><small>{detail}</small></article>; }

function LeadBoard({ leads, reload, preview, notify }: { leads: Lead[]; reload: () => Promise<void>; preview: boolean; notify: (message: string) => void }) {
  const [showForm, setShowForm] = useState(false); const [query, setQuery] = useState(''); const [sourceMode, setSourceMode] = useState<'manual' | 'csv' | 'url'>('manual'); const [form, setForm] = useState(emptyLead); const [saving, setSaving] = useState(false); const [preparedMessage, setPreparedMessage] = useState<{ companyName: string; demoUrl: string } | null>(null); const [messageKind, setMessageKind] = useState<MessageKind>('first_contact');
  const results = leads.filter((lead) => lead.deal_stage !== 'do_not_contact' && `${lead.name} ${lead.segment} ${lead.city} ${lead.state}`.toLowerCase().includes(query.toLowerCase()));
  const update = <K extends keyof typeof form>(key: K, value: (typeof form)[K]) => setForm((current) => ({ ...current, [key]: value }));
  const saveLead = async (event: FormEvent) => { event.preventDefault(); if (!form.name.trim()) return; const score = publicLeadScore(form); if (preview) { notify('No tour, registros não são gravados. Conecte o Supabase para prosseguir.'); setShowForm(false); return; } setSaving(true); try { const client = requireSupabase(); const sourceUrls = form.source_urls.filter(isPublicHttpUrl); const { error } = await client.from('leads').insert({ ...form, phone_public: normalizePhone(form.phone_public), source_urls: sourceUrls, source_checked_at: sourceUrls.length ? new Date().toISOString() : null, score: score.score, score_reasons: score.reasons }); if (error) throw error; notify('Potencial salvo. Revise as fontes antes de abordar.'); setForm(emptyLead); setShowForm(false); await reload(); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível salvar.'); } finally { setSaving(false); } };
  const acceptLead = async (lead: Lead) => { if (preview) { notify('No tour, a criação é simulada e não gera dados ou link.'); return; } try { const client = requireSupabase(); const { data, error } = await client.rpc('accept_lead_create_demo', { p_lead_id: lead.id }); if (error) throw error; const output = data as { company_slug: string; public_token: string }[]; const created = output[0]; const demoUrl = `${window.location.origin}/demonstracao/${created.public_token}`; setPreparedMessage({ companyName: lead.name, demoUrl }); notify('Demonstração preparada; revise e copie a mensagem antes de enviar manualmente.'); await reload(); } catch (error) { notify(error instanceof Error ? error.message : 'Falha ao preparar demonstração.'); } };
  return <div className="page-stack"><section className="surface prospect-controls"><div><p className="overline">FONTES PÚBLICAS</p><h2>Prospecção responsável</h2><p>Importe dados comerciais públicos, registre a URL da fonte e revise tudo antes de qualquer contato.</p></div><div className="prospect-actions"><label className="search-field"><Search size={17} /><input placeholder="Filtrar por empresa, cidade ou segmento" value={query} onChange={(e) => setQuery(e.target.value)} /></label><AppButton onClick={() => setShowForm(true)}><Plus size={17} /> Adicionar potencial</AppButton></div></section>{showForm && <section className="surface form-surface"><div className="form-head"><div><p className="overline">NOVO POTENCIAL</p><h2>Dados verificados ou a revisar</h2></div><button className="icon-button" onClick={() => setShowForm(false)}><X size={19} /></button></div><div className="segmented" role="tablist"><button className={sourceMode === 'manual' ? 'active' : ''} onClick={() => setSourceMode('manual')}>Cadastro manual</button><button className={sourceMode === 'csv' ? 'active' : ''} onClick={() => setSourceMode('csv')}>Importar CSV</button><button className={sourceMode === 'url' ? 'active' : ''} onClick={() => setSourceMode('url')}>URL pública</button></div>{sourceMode === 'csv' ? <CsvImport reload={reload} preview={preview} notify={notify} close={() => setShowForm(false)} /> : sourceMode === 'url' ? <UrlLeadForm reload={reload} preview={preview} notify={notify} close={() => setShowForm(false)} /> : <form onSubmit={saveLead}><div className="form-grid"><label>Nome da empresa<input required value={form.name} onChange={(e) => update('name', e.target.value)} /></label><label>Segmento<input value={form.segment ?? ''} onChange={(e) => update('segment', e.target.value)} placeholder="Ex.: assistência técnica" /></label><label>Cidade<input value={form.city ?? ''} onChange={(e) => update('city', e.target.value)} /></label><label>Estado<input maxLength={2} value={form.state ?? ''} onChange={(e) => update('state', e.target.value.toUpperCase())} placeholder="PR" /></label><label>Telefone comercial público<input value={form.phone_public ?? ''} onChange={(e) => update('phone_public', e.target.value)} /></label><label>E-mail comercial público<input type="email" value={form.email_public ?? ''} onChange={(e) => update('email_public', e.target.value)} /></label><label className="span-2">Site público<input type="url" value={form.website_url ?? ''} onChange={(e) => update('website_url', e.target.value)} placeholder="https://" /></label><label className="span-2">Link do Google Maps <small>(somente se informado/verificado; não é busca automática)</small><input type="url" value={form.google_maps_url ?? ''} onChange={(e) => update('google_maps_url', e.target.value)} placeholder="https://maps.google.com/..." /></label><label className="span-2">URLs das fontes <small>(uma por linha)</small><textarea value={form.source_urls.join('\n')} onChange={(e) => update('source_urls', e.target.value.split('\n').map((value) => value.trim()).filter(Boolean))} /></label><label className="checkbox span-2"><input type="checkbox" checked={form.whatsapp_verified} onChange={(e) => update('whatsapp_verified', e.target.checked)} /> WhatsApp foi divulgado explicitamente pela empresa</label></div><div className="form-actions"><p className="muted">Se um campo não estiver nas fontes, deixe em branco. Não inferimos telefone, WhatsApp ou necessidades internas.</p><AppButton type="submit" disabled={saving}>{saving ? <LoaderCircle className="spin" size={17} /> : <Check size={17} />} Salvar para revisão</AppButton></div></form>}</section>}{preparedMessage && <section className="surface message-composer"><div><p className="overline">MENSAGEM PRONTA · ENVIO MANUAL</p><h2>{messageLabels[messageKind]}</h2><p>Personalizada apenas com nome e link verificados. Copiar ou abrir uma conversa não registra contato.</p></div><label>Tipo de mensagem<select value={messageKind} onChange={(event) => setMessageKind(event.target.value as MessageKind)}>{Object.entries(messageLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><textarea readOnly value={buildMessage(messageKind, preparedMessage)} /><div className="form-actions"><span /><AppButton onClick={() => void navigator.clipboard.writeText(buildMessage(messageKind, preparedMessage)).then(() => notify('Mensagem copiada. Registre o contato somente após enviar.'))}><Copy size={16} /> Copiar mensagem</AppButton></div></section>}
    <section className="lead-list">{results.map((lead) => <article className="surface lead-card" key={lead.id}><div className="lead-top"><div><span className="initials teal">{lead.name.slice(0, 1)}</span><div><h3>{lead.name}</h3><p>{[lead.segment, lead.city, lead.state].filter(Boolean).join(' · ') || 'Localização ou segmento não encontrado nas fontes'}</p></div></div><div className="lead-score"><b>{lead.score}</b><small>adequação</small></div></div><div className="lead-evidence">{lead.score_reasons.slice(0, 3).map((reason) => <span key={reason}><Check size={14} />{reason}</span>)}</div><div className="lead-meta"><span>{lead.phone_public ? `Telefone público: ${lead.phone_public}` : 'Telefone não encontrado nas fontes'}</span><span>{lead.verification_status === 'verified' ? 'Fontes verificadas' : 'Revisão pendente'}</span>{lead.google_maps_url && <a href={lead.google_maps_url} target="_blank" rel="noreferrer">Maps informado <ExternalLink size={13} /></a>}</div><div className="lead-footer"><StatusPill state={lead.deal_stage} /><span className="sources-count">{lead.source_urls.length} fonte(s)</span><AppButton onClick={() => void acceptLead(lead)}><WandSparkles size={16} /> Aceitar cliente e criar projeto</AppButton></div></article>)}{!results.length && <EmptyState icon={Search} title="Nenhum potencial cadastrado" text="Adicione uma empresa com dados comerciais públicos, importe um CSV ou registre uma URL para revisão." action={<AppButton onClick={() => setShowForm(true)}><Plus size={16} /> Adicionar potencial</AppButton>} />}</section></div>;
}

function CsvImport({ reload, preview, notify, close }: { reload: () => Promise<void>; preview: boolean; notify: (message: string) => void; close: () => void }) {
  const [file, setFile] = useState<File | null>(null); const [working, setWorking] = useState(false);
  const importCsv = async () => { if (!file) return; setWorking(true); try { const text = await file.text(); const lines = text.split(/\r?\n/).filter(Boolean); const headers = (lines.shift() || '').split(',').map((header) => header.trim().toLowerCase()); const required = ['nome']; if (!required.every((header) => headers.includes(header))) throw new Error('O CSV precisa ter ao menos a coluna nome. Veja o modelo no tutorial.'); const entries = lines.slice(0, 100).map((line) => { const values = line.split(',').map((value) => value.trim()); const find = (key: string) => values[headers.indexOf(key)] || null; const input = { segment: find('segmento'), phone_public: normalizePhone(find('telefone')), email_public: find('email'), whatsapp_verified: find('whatsapp') === 'sim', website_url: find('site'), google_maps_url: find('google_maps') }; const score = publicLeadScore(input); return { name: find('nome') || '', city: find('cidade'), state: find('estado'), ...input, source_urls: [find('fonte')].filter(Boolean), verification_status: 'needs_review', deal_stage: 'new', notes: 'Importado por CSV; revisar fonte e permissões antes de contato.', score: score.score, score_reasons: score.reasons }; }); if (!entries.length) throw new Error('Nenhuma linha válida encontrada.'); if (preview) { notify(`No tour, ${entries.length} registros foram apenas lidos localmente e não salvos.`); close(); return; } const client = requireSupabase(); const { error } = await client.from('leads').upsert(entries, { onConflict: 'dedupe_key', ignoreDuplicates: true }); if (error) throw error; notify(`${entries.length} linhas processadas. Duplicatas foram ignoradas quando reconhecidas.`); close(); await reload(); } catch (error) { notify(error instanceof Error ? error.message : 'Falha ao importar CSV.'); } finally { setWorking(false); } };
  return <div className="import-box"><FileText size={24} /><h3>Importar lista que você já possui</h3><p>Formato aceito: CSV UTF-8 com colunas como <code>nome,cidade,estado,segmento,telefone,email,site,google_maps,fonte</code>. Fórmulas perigosas são neutralizadas na exportação; revise a fonte de todos os dados.</p><input type="file" accept=".csv,text/csv" onChange={(e) => setFile(e.target.files?.[0] || null)} /><AppButton disabled={!file || working} onClick={() => void importCsv()}>{working ? <LoaderCircle className="spin" size={17} /> : <FileText size={17} />} Processar até 100 linhas</AppButton></div>;
}

function UrlLeadForm({ reload, preview, notify, close }: { reload: () => Promise<void>; preview: boolean; notify: (message: string) => void; close: () => void }) {
  const [url, setUrl] = useState(''); const [name, setName] = useState(''); const [saving, setSaving] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!isPublicHttpUrl(url)) { notify('Informe uma URL pública HTTP ou HTTPS válida.'); return; } if (!name.trim()) { notify('Informe o nome que aparece na fonte.'); return; } if (preview) { notify('No tour, a URL não é acessada. Nada foi gravado.'); close(); return; } setSaving(true); try { const client = requireSupabase(); const score = publicLeadScore({ segment: null, phone_public: null, email_public: null, whatsapp_verified: false, website_url: url, google_maps_url: null }); const { error } = await client.from('leads').insert({ name, website_url: url, source_urls: [url], source_checked_at: new Date().toISOString(), verification_status: 'needs_review', deal_stage: 'new', score: score.score, score_reasons: score.reasons, notes: 'Adicionado por URL pública; completar e verificar manualmente.' }); if (error) throw error; notify('Potencial adicionado para revisão.'); close(); await reload(); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível salvar a URL.'); } finally { setSaving(false); } };
  return <form onSubmit={submit}><div className="form-grid"><label className="span-2">URL pública consultada<input required type="url" placeholder="https://www.exemplo.com.br" value={url} onChange={(e) => setUrl(e.target.value)} /></label><label className="span-2">Nome encontrado na fonte<input required value={name} onChange={(e) => setName(e.target.value)} /></label></div><p className="info-callout"><ShieldCheck size={17} /> O sistema deve bloquear URLs internas e não tenta contornar login, CAPTCHA ou bloqueios. Confirme manualmente contatos antes de cadastrar.</p><div className="form-actions"><span /><AppButton type="submit" disabled={saving}>{saving ? <LoaderCircle className="spin" size={17} /> : <Plus size={17} />} Salvar para revisão</AppButton></div></form>;
}

function DemoList({ companies, preview, notify }: { companies: Company[]; preview: boolean; notify: (message: string) => void }) {
  const demos = companies.filter((company) => company.lifecycle === 'demo');
  const copy = async (value: string) => { await navigator.clipboard.writeText(value); notify('Link copiado. O envio continua manual.'); };
  return <div className="page-stack"><section className="surface intro-row"><div><p className="overline">PRÉVIAS RESPONSÁVEIS</p><h2>Demonstrações não são sites oficiais.</h2><p>Cada prévia identifica a proposta, não aceita reservas nem coleta dados de consumidores. Revise campos ausentes antes de compartilhar.</p></div><span className="feature-chip"><ShieldCheck size={16} /> Sem reservas ativas</span></section><section className="card-grid">{demos.map((company) => <article className="surface demo-card" key={company.id}><div className={`demo-cover theme-${company.theme_key}`}><span>PROPOSTA · NICOLAS</span><CalendarDays size={31} /></div><div className="demo-card-body"><StatusPill state="demo" /><h3>{company.name}</h3><p>{company.description || 'Descrição pendente de confirmação.'}</p><small>{company.demo_expires_at ? `Expira em ${new Intl.DateTimeFormat('pt-BR').format(new Date(company.demo_expires_at))}` : 'Expiração não configurada'}</small><div><AppButton variant="secondary" onClick={() => window.open(`/demonstracao/${company.public_token}`, '_blank', 'noopener,noreferrer')}>Ver prévia <ExternalLink size={15} /></AppButton><AppButton variant="ghost" onClick={() => void copy(`${window.location.origin}/demonstracao/${company.public_token}`)}><Copy size={15} /> Copiar</AppButton></div></div></article>)}{!demos.length && <EmptyState icon={WandSparkles} title="Nenhuma demonstração preparada" text="Aceite um potencial revisado para criar uma demonstração editável no mesmo cadastro." />}</section>{preview && <p className="quiet-note">Os dados desta visualização não representam empresas ou demonstrações reais.</p>}</div>;
}

function DealsBoard({ leads, reload, preview, notify }: { leads: Lead[]; reload: () => Promise<void>; preview: boolean; notify: (message: string) => void }) {
  const stages: DealStage[] = ['new', 'analyzed', 'demo_prepared', 'contacted', 'replied', 'interested', 'proposal_sent', 'won', 'lost', 'do_not_contact'];
  const move = async (lead: Lead, stage: DealStage) => { if (stage === lead.deal_stage) return; if (preview) { notify('No tour, a negociação não é persistida.'); return; } try { const client = requireSupabase(); const { error } = await client.from('leads').update({ deal_stage: stage }).eq('id', lead.id); if (error) throw error; if (stage === 'do_not_contact') notify('Empresa marcada como Não contatar e removida de novas sugestões.'); await reload(); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível atualizar a negociação.'); } };
  return <div className="page-stack"><section className="surface intro-row"><div><p className="overline">FUNIL COMERCIAL</p><h2>Registre o que aconteceu, não o que imagina.</h2><p>Copiar uma mensagem ou abrir uma conversa não marca contato. Atualize a etapa somente depois da ação real.</p></div></section><div className="kanban">{stages.map((stage) => { const items = leads.filter((lead) => lead.deal_stage === stage); return <section className="kanban-column" key={stage}><header><span>{dealStageLabels[stage]}</span><b>{items.length}</b></header>{items.map((lead) => <article className="deal-card" key={lead.id}><span className="initials">{lead.name.slice(0, 1)}</span><strong>{lead.name}</strong><small>{lead.segment || 'Segmento não informado'}</small><select value={lead.deal_stage} onChange={(e) => void move(lead, e.target.value as DealStage)} aria-label={`Etapa de ${lead.name}`}>{stages.map((option) => <option value={option} key={option}>{dealStageLabels[option]}</option>)}</select>{lead.next_action_at && <p><CalendarDays size={13} /> {new Intl.DateTimeFormat('pt-BR').format(new Date(lead.next_action_at))}</p>}</article>)}{!items.length && <div className="kanban-empty">Sem registros</div>}</section>; })}</div></div>;
}

function CompanyList({ companies, preview, notify }: { companies: Company[]; preview: boolean; notify: (message: string) => void }) {
  const [show, setShow] = useState(false); const [name, setName] = useState(''); const [theme, setTheme] = useState<Company['theme_key']>('professional');
  const create = async (event: FormEvent) => { event.preventDefault(); if (preview) { notify('No tour, empresas não são criadas.'); setShow(false); return; } try { const client = requireSupabase(); const slug = name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''); const { error } = await client.from('companies').insert({ name, slug: `${slug}-${crypto.randomUUID().slice(0, 5)}`, theme_key: theme, lifecycle: 'demo', booking_enabled: false }); if (error) throw error; notify('Empresa criada como demonstração. Complete dados e aprove antes de ativar.'); setShow(false); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível criar empresa.'); } };
  return <div className="page-stack"><section className="surface intro-row"><div><p className="overline">EMPRESAS</p><h2>Um cadastro, uma configuração, um ciclo de vida claro.</h2><p>Crie em demonstração, complete informações confirmadas e só ative reservas depois da conferência.</p></div><AppButton onClick={() => setShow(!show)}><Plus size={17} /> Nova empresa</AppButton></section>{show && <section className="surface form-surface"><form onSubmit={create}><div className="form-grid"><label>Nome da empresa<input required value={name} onChange={(e) => setName(e.target.value)} /></label><label>Tema<select value={theme} onChange={(e) => setTheme(e.target.value as Company['theme_key'])}><option value="beauty">Beleza e estética</option><option value="maintenance">Manutenção e assistência</option><option value="professional">Serviços profissionais</option></select></label></div><div className="form-actions"><p className="muted">A empresa será criada como demonstração e sem reservas.</p><AppButton type="submit"><Plus size={17} /> Criar demonstração</AppButton></div></form></section>}<section className="company-table surface"><div className="table-head"><span>Empresa</span><span>Estado</span><span>Tema</span><span>Link público</span><span /></div>{companies.map((company) => <div className="table-row" key={company.id}><div><strong>{company.name}</strong><small>{[company.city, company.state].filter(Boolean).join(' · ') || 'Endereço pendente'}</small></div><StatusPill state={company.lifecycle} /><span className="theme-name">{company.theme_key === 'beauty' ? 'Beleza' : company.theme_key === 'maintenance' ? 'Manutenção' : 'Profissional'}</span><a href={company.lifecycle === 'active' ? `/agenda/${company.slug}` : `/demonstracao/${company.public_token}`} target="_blank" rel="noreferrer">Abrir <ExternalLink size={14} /></a><button className="icon-button"><MoreHorizontal size={18} /></button></div>)}{!companies.length && <EmptyState icon={Store} title="Nenhuma empresa cadastrada" text="Você pode criar uma demonstração manual ou aceitar um potencial revisado." />}</section></div>;
}

function AgendaView({ companies, preview }: { companies: Company[]; preview: boolean }) { const active = companies.filter((company) => company.lifecycle === 'active'); return <div className="page-stack"><section className="surface intro-row"><div><p className="overline">AGENDA DA EMPRESA</p><h2>Operações persistidas, sem conflito de horários.</h2><p>Visualizações diária, semanal e mensal são alimentadas por reservas reais após ativação da empresa.</p></div><div className="view-switch"><button className="active">Semana</button><button>Mês</button><button>Lista</button></div></section>{active.length ? <section className="surface calendar-placeholder"><div className="calendar-toolbar"><ChevronLeft size={18} /><strong>Agenda operacional</strong><ChevronRight size={18} /></div><div className="calendar-grid">{['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom'].map((day) => <div key={day}><strong>{day}</strong><span>—</span></div>)}</div><p>Selecione uma empresa e aguarde as reservas reais carregarem.</p></section> : <EmptyState icon={CalendarDays} title="Nenhuma agenda ativa" text={preview ? 'No tour, as reservas não são representadas por dados fictícios.' : 'Ative uma empresa depois de confirmar serviços, preços, duração, horários, contatos e acesso administrativo.'} />}</div>; }

function ServiceManager({ companies, preview, notify }: { companies: Company[]; preview: boolean; notify: (message: string) => void }) { const [open, setOpen] = useState(false); const [name, setName] = useState(''); const [priceType, setPriceType] = useState<'fixed' | 'manual'>('fixed'); const [price, setPrice] = useState(''); const [duration, setDuration] = useState('60'); const target = companies[0]; const submit = async (event: FormEvent) => { event.preventDefault(); if (!target) { notify('Cadastre uma empresa antes de criar serviços.'); return; } if (preview) { notify('No tour, serviços não são gravados.'); setOpen(false); return; } try { const parsedPriceCents = Math.round(Number(price.replace(',', '.')) * 100); const priceCents = priceType === 'fixed' ? parsedPriceCents : null; if (priceType === 'fixed' && (!Number.isInteger(parsedPriceCents) || parsedPriceCents < 0)) throw new Error('Informe um preço válido.'); const client = requireSupabase(); const { error } = await client.from('services').insert({ company_id: target.id, name, price_type: priceType, price_cents: priceCents, duration_minutes: Number(duration), buffer_minutes: 0 }); if (error) throw error; notify('Serviço salvo. O valor é recalculado no servidor em cada reserva.'); setOpen(false); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível criar serviço.'); } }; return <div className="page-stack"><section className="surface intro-row"><div><p className="overline">CATÁLOGO DE SERVIÇOS</p><h2>Preço fixo ou avaliação manual.</h2><p>Valores definitivos são calculados no banco. Serviços sob avaliação nunca são confirmados automaticamente com preço inventado.</p></div><AppButton onClick={() => setOpen(!open)}><Plus size={17} /> Novo serviço</AppButton></section>{open && <section className="surface form-surface"><form onSubmit={submit}><div className="form-grid"><label>Nome do serviço<input required value={name} onChange={(e) => setName(e.target.value)} /></label><label>Duração em minutos<input required min="5" max="1440" type="number" value={duration} onChange={(e) => setDuration(e.target.value)} /></label><label>Forma de preço<select value={priceType} onChange={(e) => setPriceType(e.target.value as 'fixed' | 'manual')}><option value="fixed">Preço fixo</option><option value="manual">Avaliação manual</option></select></label>{priceType === 'fixed' && <label>Preço em R$<input required inputMode="decimal" value={price} onChange={(e) => setPrice(e.target.value)} placeholder="0,00" /></label>}</div><div className="form-actions"><span /><AppButton type="submit"><Check size={17} /> Salvar serviço</AppButton></div></form></section>}<EmptyState icon={FileText} title="Serviços por empresa" text={target ? `Cadastre os serviços confirmados de ${target.name}.` : 'Crie uma empresa para administrar serviços.'} /></div>; }

function SettingsView() { return <div className="page-stack"><section className="surface settings-grid"><div><p className="overline">CONFIGURAÇÃO INICIAL</p><h2>Conexões e consumo</h2><p>As configurações com segredo ficam no painel do Supabase ou nas variáveis protegidas da Cloudflare. Esta tela não exibe nem armazena chaves.</p></div><div className="settings-list"><div><span className="icon-disc"><ShieldCheck size={17} /></span><div><strong>Autenticação</strong><small>Supabase Auth com recuperação de senha</small></div><StatusPill state="configurar" /></div><div><span className="icon-disc"><Sparkles size={17} /></span><div><strong>IA opcional</strong><small>Use somente após definir provedor, limite e chave no servidor</small></div><StatusPill state="desativada" /></div><div><span className="icon-disc"><Search size={17} /></span><div><strong>Busca de potenciais</strong><small>CSV e URL pública disponíveis; Maps automático não configurado</small></div><StatusPill state="manual" /></div></div></section><section className="surface"><div className="section-title"><div><p className="overline">LIMITES APLICADOS</p><h2>Proteções operacionais</h2></div></div><div className="checklist-row"><div><CheckCircle2 size={18} /><span>Importação limitada a 100 linhas por lote</span></div><div><CheckCircle2 size={18} /><span>URLs públicas validadas antes de encaminhar</span></div><div><CheckCircle2 size={18} /><span>Links de demonstração revogáveis</span></div><div><CheckCircle2 size={18} /><span>Auditoria de operações administrativas</span></div></div></section></div>; }

export default function App() {
  const [path, navigate] = usePath(); const [sessionReady, setSessionReady] = useState(false); const [hasSession, setHasSession] = useState(false); const publicMatch = path.match(/^\/agenda\/([^?]+)/); const demoMatch = path.match(/^\/demonstracao\/([^?]+)/); const tour = new URLSearchParams(window.location.search).get('tour') === '1';
  useEffect(() => { if (!supabase) { setSessionReady(true); return; } let alive = true; void supabase.auth.getSession().then(({ data }) => { if (alive) { setHasSession(Boolean(data.session)); setSessionReady(true); } }); const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => { setHasSession(Boolean(session)); setSessionReady(true); }); return () => { alive = false; listener.subscription.unsubscribe(); }; }, []);
  if (publicMatch) return <PublicBooking slug={decodeURIComponent(publicMatch[1])} navigate={navigate} />;
  if (demoMatch) return <DemoPage token={decodeURIComponent(demoMatch[1])} navigate={navigate} />;
  if (!isSupabaseConfigured && !tour) return <Setup navigate={navigate} />;
  if (!sessionReady && !tour) return <div className="public-loading"><LoaderCircle className="spin" /> Iniciando sessão segura...</div>;
  if (path.startsWith('/recuperar-acesso')) return <RecoverAccess navigate={navigate} />;
  if ((path.startsWith('/login') || path === '/') && !hasSession && !tour) return <Login navigate={navigate} />;
  return <Dashboard preview={tour} navigate={navigate} />;
}
